; fast.asm -- chapter 12: 6,144 bytes filled, one at a time and with PUSH
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "fast.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
keep    EQU VARS               ; a word of RAM for SP
; 6,144 bytes from $D000 filled twice: one byte at a time by slow, and two
; at a time with PUSH by quick. The interrupts are off throughout.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
f1:     call slow
f2:     call quick
f3:     nop
stop:   jr stop

; slow: the bytes filled with $AA, one at a time
slow:   ld hl, $D000
        ld a, $AA
        ld c, 24                ; 24 x 256 bytes
sl1:    ld b, 0
sl2:    ld (hl), a
        inc hl
        djnz sl2
        dec c
        jr nz, sl1
        ret

; quick: the bytes filled with $55, two at a time, from the end down
quick:  ld (keep), sp           ; the real stack, for later
        ld sp, $E800            ; SP just past the end of the bytes
        ld hl, $5555
        ld b, 192               ; 192 x 32 bytes
qu1:    DUP 16                  ; sjasmplus writes the next line 16 times
        push hl
        EDUP
        djnz qu1
        ld sp, (keep)           ; the real stack back
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
